package net.local.picocapture;
import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;

/** RTSP interleaved RTP/MP2T plus optional MPEG-TS UDP destination. */
final class DesktopOutputs implements AutoCloseable{
 final RootCapture root;final CopyOnWriteArrayList<RootCapture.Client> sinks=new CopyOnWriteArrayList<>();ServerSocket server;DatagramSocket udp;volatile boolean running=true;volatile long resyncs;int rtspPort;String status="";
 DesktopOutputs(RootCapture root,int port,String destination){this.root=root;rtspPort=port;if(port>0)try{server=new ServerSocket();server.setReuseAddress(true);server.bind(new InetSocketAddress(port));new Thread(this::accept,"capture-rtsp").start();status="RTSP TCP ready";}catch(Exception e){status="RTSP unavailable: "+e;System.out.println(status);}
  if(!destination.trim().isEmpty())try{int cut=destination.lastIndexOf(':');if(cut<1)throw new IOException("Use IP:port");InetAddress host=InetAddress.getByName(destination.substring(0,cut));int p=Integer.parseInt(destination.substring(cut+1));if(p<1024||p>65535)throw new IOException("UDP port must be 1024..65535");udp=new DatagramSocket();RootCapture.Client c=new RootCapture.Client(null);sinks.add(c);new Thread(()->sendUdp(c,host,p),"capture-udp").start();status+="; UDP ready: "+destination;}catch(Exception e){status+="; UDP unavailable: "+e;System.out.println(status);}
 }
 void publish(byte[] packet,boolean key,byte[] tables){for(RootCapture.Client c:sinks)if(!c.enqueue(packet,key,tables)){resyncs++;root.syncRequested=true;}}
 void sendUdp(RootCapture.Client c,InetAddress host,int port){try{while(running&&root.running){byte[] data=c.queue.poll(2,TimeUnit.SECONDS);if(data==null)continue;for(int offset=0;offset<data.length;offset+=1316){int size=Math.min(1316,data.length-offset);udp.send(new DatagramPacket(data,offset,size,host,port));}}}catch(Exception e){if(running)System.out.println("UDP output: "+e);}finally{sinks.remove(c);}}
 void accept(){while(running)try{Socket s=server.accept();s.setTcpNoDelay(true);s.setSendBufferSize(32768);new Thread(()->serve(s),"rtsp-client").start();}catch(Exception e){if(running)System.out.println("RTSP accept: "+e);}}
 void response(OutputStream out,int code,String seq,String headers,String body)throws IOException{synchronized(out){byte[] b=body.getBytes("UTF-8");String text="RTSP/1.0 "+code+(code==200?" OK":" Unsupported Transport")+"\r\nCSeq: "+seq+"\r\nServer: PicoCapture\r\n"+headers+(b.length>0?"Content-Length: "+b.length+"\r\n":"")+"\r\n";out.write(text.getBytes("UTF-8"));out.write(b);out.flush();}}
 static String line(InputStream in)throws IOException{int first=in.read();while(first=='$'){int channel=in.read(),high=in.read(),low=in.read();if(low<0)return null;int bytes=(high<<8)|low;while(bytes>0){long skipped=in.skip(bytes);if(skipped==0){if(in.read()<0)return null;skipped=1;}bytes-=skipped;}first=in.read();}if(first<0)return null;ByteArrayOutputStream b=new ByteArrayOutputStream();while(first!='\n'&&first>=0){if(first!='\r')b.write(first);if(b.size()>8192)throw new IOException("RTSP line too large");first=in.read();}return b.toString("UTF-8");}
 void serve(Socket socket){RootCapture.Client client=null;try{socket.setSoTimeout(15000);InputStream in=new BufferedInputStream(socket.getInputStream());OutputStream out=socket.getOutputStream();String session=UUID.randomUUID().toString().replace("-","");int channel=0;while(running&&root.running){String first=line(in);if(first==null)return;if(first.isEmpty())continue;String[] words=first.split(" ");if(words.length<2)return;Map<String,String> headers=new HashMap<>();String line;int n=0;while((line=line(in))!=null&&!line.isEmpty()){n+=line.length();if(n>8192)throw new IOException("RTSP headers too large");int colon=line.indexOf(':');if(colon>0)headers.put(line.substring(0,colon).toLowerCase(Locale.US),line.substring(colon+1).trim());}String seq=headers.getOrDefault("cseq","1"),method=words[0];
    if(method.equals("OPTIONS"))response(out,200,seq,"Public: OPTIONS, DESCRIBE, SETUP, PLAY, GET_PARAMETER, TEARDOWN\r\n","");
    else if(method.equals("DESCRIBE")){String sdp="v=0\r\no=- 0 0 IN IP4 127.0.0.1\r\ns=Pico Capture\r\nc=IN IP4 0.0.0.0\r\nt=0 0\r\na=control:*\r\nm=video 0 RTP/AVP 33\r\na=rtpmap:33 MP2T/90000\r\na=control:track1\r\n";response(out,200,seq,"Content-Type: application/sdp\r\nContent-Base: rtsp://"+socket.getLocalAddress().getHostAddress()+":"+rtspPort+"/live/\r\n",sdp);}
    else if(method.equals("SETUP")){String transport=headers.getOrDefault("transport","");if(!transport.toUpperCase(Locale.US).contains("RTP/AVP/TCP")){response(out,461,seq,"","");continue;}int index=transport.indexOf("interleaved=");if(index>=0){String pair=transport.substring(index+12).split(";")[0];channel=Integer.parseInt(pair.split("-")[0]);}if(channel<0||channel>254)throw new IOException("Invalid channel");response(out,200,seq,"Session: "+session+";timeout=60\r\nTransport: RTP/AVP/TCP;unicast;interleaved="+channel+"-"+(channel+1)+"\r\n","");}
    else if(method.equals("PLAY")){response(out,200,seq,"Session: "+session+"\r\nRange: npt=0.000-\r\n","");socket.setSoTimeout(0);if(client==null){client=new RootCapture.Client(socket);sinks.add(client);final RootCapture.Client active=client;final int ch=channel;new Thread(()->sendRtp(active,out,ch),"capture-rtp").start();root.syncRequested=true;}}
    else if(method.equals("TEARDOWN")){response(out,200,seq,"Session: "+session+"\r\n","");return;}
    else response(out,200,seq,"Session: "+session+"\r\n","");
   }
  }catch(Exception e){if(running)System.out.println("RTSP client: "+e);}finally{if(client!=null)sinks.remove(client);try{socket.close();}catch(Exception ignored){}}}
 void sendRtp(RootCapture.Client c,OutputStream out,int channel){int sequence=0,ssrc=new Random().nextInt();long start=System.nanoTime();try{while(running&&root.running&&!c.socket.isClosed()){byte[] data=c.queue.poll(2,TimeUnit.SECONDS);if(data==null)continue;for(int offset=0;offset<data.length;offset+=1316){int n=Math.min(1316,data.length-offset),length=n+12;long timestamp=(System.nanoTime()-start)*9/100000;byte[] h=new byte[]{'$',(byte)channel,(byte)(length>>8),(byte)length,(byte)0x80,33,(byte)(sequence>>8),(byte)sequence,(byte)(timestamp>>24),(byte)(timestamp>>16),(byte)(timestamp>>8),(byte)timestamp,(byte)(ssrc>>24),(byte)(ssrc>>16),(byte)(ssrc>>8),(byte)ssrc};sequence++;synchronized(out){out.write(h);out.write(data,offset,n);out.flush();}}}}catch(Exception e){if(running)System.out.println("RTP writer: "+e);}finally{sinks.remove(c);c.close();}}
 public void close(){running=false;for(RootCapture.Client c:sinks)c.close();sinks.clear();try{if(server!=null)server.close();}catch(Exception ignored){}if(udp!=null)udp.close();}
}
